package com.gymmind.ai.infrastructure.bailian; import java.util.*; public final class EmbeddingDimension { public static final int DIMENSIONS=1024; private EmbeddingDimension(){} public static boolean validate(List<float[]> vectors,int expected){if(vectors==null||vectors.size()!=expected)throw new IllegalArgumentException("embedding batch mismatch");for(float[] v:vectors)if(v==null||v.length!=DIMENSIONS)throw new IllegalArgumentException("embedding dimension must be 1024");return true;} }
